public class AIRecommendationJobFactory(string resourceName = null, Action<Humidifier.SageMaker.AIRecommendationJob> factoryAction = null) : ResourceFactory<Humidifier.SageMaker.AIRecommendationJob>(resourceName)
{

    internal InnerAIRecommendationJobAIRecommendationOutputConfigFactory OutputConfigFactory { get; set; }

    internal InnerAIRecommendationJobAIRecommendationInferenceSpecificationFactory InferenceSpecificationFactory { get; set; }

    internal InnerAIRecommendationJobAIRecommendationPerformanceTargetFactory PerformanceTargetFactory { get; set; }

    internal InnerAIRecommendationJobAIRecommendationComputeSpecFactory ComputeSpecFactory { get; set; }

    internal InnerAIRecommendationJobAIModelSourceFactory ModelSourceFactory { get; set; }

    protected override Humidifier.SageMaker.AIRecommendationJob Create()
    {
        var aIRecommendationJobResult = CreateAIRecommendationJob();
        factoryAction?.Invoke(aIRecommendationJobResult);

        return aIRecommendationJobResult;
    }

    private Humidifier.SageMaker.AIRecommendationJob CreateAIRecommendationJob()
    {
        var aIRecommendationJobResult = new Humidifier.SageMaker.AIRecommendationJob
        {
            GivenName = InputResourceName,
        };

        return aIRecommendationJobResult;
    }
    public override void CreateChildren(Humidifier.SageMaker.AIRecommendationJob result)
    {
        base.CreateChildren(result);

        result.OutputConfig ??= OutputConfigFactory?.Build();
        result.InferenceSpecification ??= InferenceSpecificationFactory?.Build();
        result.PerformanceTarget ??= PerformanceTargetFactory?.Build();
        result.ComputeSpec ??= ComputeSpecFactory?.Build();
        result.ModelSource ??= ModelSourceFactory?.Build();
    }

} // End Of Class

